use crate::headers::map::{HeaderMap, HeaderName};
use crate::hop::Hop;

/// Lowercase header names and keep a stable order.
pub fn normalize_headers(map: &mut HeaderMap, hop: Hop) -> Result<(), Error> {
    let mut out = HeaderMap::with_capacity(map.len());
    for (name, value) in map.iter_ordered_mut() {
        let lower = name.as_str().to_ascii_lowercase();
        *name = HeaderName::from_lowercase(lower)?;
        out.append(name.clone(), value.clone());
    }
    *map = out;
    Ok(())
}

/// Drop hop-by-hop headers before forwarding.
pub fn strip_hop_by_hop(map: &mut HeaderMap) {
    for name in HOP_BY_HOP {
        map.remove(*name);
    }
}

const HOP_BY_HOP: &[&str] = &[
    "connection", "keep-alive", "proxy-connection",
    "te", "trailer", "transfer-encoding", "upgrade",
];

