use crate::request::Request;

/// Decides whether a route applies to a request.
/// Seam: implementations land in separate changes.
pub trait RouteMatcher: Send + Sync {
    fn matches(&self, req: &Request) -> bool;
    fn priority(&self) -> u16 { 100 }
}

use std::time::Duration;

pub struct RetryPolicy {
    pub max_attempts: u8,
    pub base: Duration,
}

pub fn retry_with_budget<F, T>(policy: &RetryPolicy, mut f: F) -> Result<T, Error>
where F: FnMut() -> Result<T, Error> {
    let mut last = None;
    for attempt in 0..policy.max_attempts {
        match f() {
            Ok(v) => return Ok(v),
            Err(e) => { last = Some(e); sleep(policy.base * 2u32.pow(attempt as u32)); }
        }
    }
    Err(last.unwrap())
}
